CREATE TABLE music_playback_session (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,track_id UUID NOT NULL,source_id UUID NOT NULL,queue_id UUID,state VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',started_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,last_activity_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,ended_at TIMESTAMPTZ,position_millis BIGINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,CHECK(state IN ('ACTIVE','COMPLETED','SKIPPED','ABANDONED')),CHECK(position_millis>=0),CHECK(version>=0),CHECK((state='ACTIVE' AND ended_at IS NULL) OR (state<>'ACTIVE' AND ended_at IS NOT NULL)),FOREIGN KEY(track_id) REFERENCES music_track(id),FOREIGN KEY(source_id) REFERENCES music_audio_source(id),FOREIGN KEY(queue_id) REFERENCES music_queue(id));
CREATE TABLE music_playback_history (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,track_id UUID NOT NULL,source_id UUID NOT NULL,started_at TIMESTAMPTZ NOT NULL,ended_at TIMESTAMPTZ NOT NULL,listened_millis BIGINT NOT NULL DEFAULT 0,outcome VARCHAR(16) NOT NULL,CHECK(ended_at>=started_at),CHECK(listened_millis>=0),CHECK(outcome IN ('COMPLETED','SKIPPED','ABANDONED')),FOREIGN KEY(track_id) REFERENCES music_track(id),FOREIGN KEY(source_id) REFERENCES music_audio_source(id));
CREATE INDEX idx_music_playback_history_owner ON music_playback_history(owner_id,ended_at DESC);
